    [1] = { t = 0, act = function(o)            -- `ins_96 SHOOT_FAN_AIMED(type3, col li7, speed 0)`
        EX.shoot(o, o.x, o.y, {
            op = 96, type = S100_TYPE, color = EX.color(o.fam_li7),
            count1 = 1, count2 = 1, speed1 = 0, speed2 = S100_SPEED2,
